-- Catálogo de referência (decisão de 20/10/2026): produtos reais das marcas, com dados das fichas técnicas
-- oficiais e preço de mercado só quando encontrado (com fonte e data). Não pertence a nenhum vendedor: serve
-- para o cliente indicar preferências no pedido e para comparar propostas. Os fornecedores ligam a sua
-- oferta a estes produtos. Sem fotografias (direitos das marcas): carregadas pelas marcas ou fornecedores.
create table public.reference_products (
  id uuid primary key default gen_random_uuid(),
  marca text not null,
  nome text not null,
  tipo public.product_type not null,
  descricao text,
  acabamento text,
  uso text,
  embalagens_l numeric[] not null default '{}',
  rendimento_m2_l numeric,
  demaos text,
  secagem_horas numeric,
  diluicao text,
  cores text,
  base_aquosa boolean,
  url_produto text,
  url_ficha_tecnica text,
  preco_referencia_cents integer check (preco_referencia_cents > 0),
  preco_embalagem_l numeric,
  preco_fonte text,
  preco_data date,
  complementares text[] not null default '{}',
  nota text,
  foto_path text,
  created_at timestamptz not null default now(),
  unique (marca, nome)
);
alter table public.reference_products enable row level security;
revoke all on public.reference_products from anon;
create policy reference_products_select on public.reference_products for select to authenticated using (true);
create policy reference_products_admin on public.reference_products for all to authenticated
  using ((select private.is_platform_admin())) with check ((select private.is_platform_admin()));

-- A oferta de um fornecedor pode corresponder a um produto de referência.
alter table public.products add column reference_product_id uuid references public.reference_products (id) on delete set null;
create index products_reference_idx on public.products (reference_product_id);

-- Produtos preferidos no pedido: [{"id": uuid, "fixo": bool}]; "fixo" = o pintor não deve substituir.
alter table public.work_requests add column produtos_preferidos jsonb not null default '[]'::jsonb;
alter table public.request_listings add column produtos_preferidos jsonb not null default '[]'::jsonb;

create or replace function private.listing_via_publica() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.status = 'publicado' then
    update public.request_listings
      set ocupacao_via_publica = new.ocupacao_via_publica, produtos_preferidos = new.produtos_preferidos
      where request_id = new.id;
  end if;
  return new;
end $$;

